import java.util.*;

class Solution {
  public int minimumOperations(List<Integer> nums) {
    int[] dp = {0, 0, 0};
    for (int value : nums) {
      int[] next = {Integer.MAX_VALUE / 2, Integer.MAX_VALUE / 2, Integer.MAX_VALUE / 2};
      for (int group = 0; group < 3; group++) {
        int cost = value == group + 1 ? 0 : 1;
        for (int previous = 0; previous <= group; previous++)
          next[group] = Math.min(next[group], dp[previous] + cost);
      }
      dp = next;
    }
    return Math.min(dp[0], Math.min(dp[1], dp[2]));
  }
}
